import 'package:data_fixture_dart/data_fixture_dart.dart';

class Company {final String name;final List<Person> employees;Company({this.name,this.employees});}

extension CompanyFixture on Company {static _CompanyFixtureFactory factory()=>_CompanyFixtureFactory();}

class _CompanyFixtureFactory extends FixtureFactory<Company>{
  @override
  FixtureDefinition<Company> definition()=>define((faker, [i=0])=>Company(name: faker.company.name(),employees: []));
}

void main(){
  final company = CompanyFixture.factory().makeSingle();
  print(company.name);
}
